//! The central object for emitting type-checked JVM bytecode.
//!
//! Port of `ghidra.pcode.emu.jit.gen.util.Emitter`.
//!
//! The emitter wraps an ASM `MethodVisitor` and encodes the (locally known) contents of the JVM
//! operand stack in its type parameter `N`, so that the compiler rejects generated bytecode that
//! would be inconsistent -- e.g., an `iload` followed by an `lstore`. Stack contents are encoded
//! as a Lisp-style list: the empty stack is [`Bot`], and [`Ent<N, T>`](Ent) is the stack `N` with
//! an entry of machine type `T` pushed on top. The head of the list, i.e., `N` itself, is the top
//! of the stack.
//!
//! # Differences from Java
//!
//! - Java's `Next`, `Ent`, `Bot`, and `Dead` are nested marker interfaces, since Java has no way
//!   to build a type-level list from anything but types. Here [`Next`] remains a marker trait, but
//!   [`Bot`] and [`Ent`] are marker *structs* implementing it. Rust has no subtyping between
//!   them, so a generator that wants "any stack with a `TInt` on top" simply writes
//!   `Emitter<Ent<N, TInt>>` instead of Java's `N0 extends Ent<N1, TInt>` bound -- which also
//!   makes Java's `Misc.cast1` workaround unnecessary. Java's private `SingletonEnt` (the one
//!   value cast to every shape) becomes the unit values [`BOTTOM`] and [`Ent::new`].
//! - Java's `A3Function`..`A8Function` and `A3Consumer`/`A4Consumer` nested interfaces exist only
//!   because Java cannot partially apply a method reference. Rust closures can, so the [`emit`]
//!   family takes plain `FnOnce` bounds instead. [`Emitter::emit1`]..[`Emitter::emit7`] carry the
//!   argument count in the name, since Rust has no overloading.
//! - Java's overloaded statics `start(ClassVisitor, ..)` and `start(TRef, ClassVisitor, ..)`
//!   become the free functions [`start_static`] and [`start_instance`], following the convention
//!   set by [`local::decl`](crate::pcode::emu::jit::gen::util::local::decl) for Java statics.
//! - Java copies of an emitter (produced by the unchecked `(Emitter) em` casts throughout `Op`)
//!   all reference the *same* `MethodVisitor` and root scope. Here that aliasing is explicit:
//!   both are held behind `Arc<Mutex<_>>`, so [`Emitter::recast`] and [`Clone`] preserve it.

use std::marker::PhantomData;
use std::sync::{Arc, Mutex, MutexGuard};

use crate::format::javaclass::flags::methods_info_access_flags::ACC_STATIC;
use crate::pcode::emu::jit::gen::util::root_scope::RootScope;
use crate::pcode::emu::jit::gen::util::types::{BNonVoid, BType, TRef};
use crate::pcode::seam_stubs::{ClassVisitor, Def, Label, MethodVisitor, MthDesc, ObjDef};

/// Stack contents.
///
/// Port of `Emitter.Next`. Implemented by [`Bot`] and [`Ent`], and by the stack shapes generator
/// code defines for itself. Purely a marker: it exists to leverage the type checker.
pub trait Next {}

/// The bottom of the stack, i.e., the empty stack.
///
/// Port of `Emitter.Bot`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Bot;

impl Next for Bot {}

/// The bottom of the stack.
///
/// Port of `Emitter.Next.BOTTOM`. In Java this is the sole `SingletonEnt` instance, cast to
/// whatever stack shape is required; here each shape has its own unit value.
pub const BOTTOM: Bot = Bot;

/// An entry on the stack.
///
/// Port of `Emitter.Ent<N, T>`. `N` is the tail (the portion below this entry) of the stack, and
/// `T` is the machine type of the entry itself.
pub struct Ent<N: Next, T: BNonVoid>(PhantomData<(N, T)>);

impl<N: Next, T: BNonVoid> Ent<N, T> {
    /// The value of this stack shape, for use where a witness is required, e.g., [`assume`].
    pub const fn new() -> Self {
        Self(PhantomData)
    }
}

impl<N: Next, T: BNonVoid> Next for Ent<N, T> {}

impl<N: Next, T: BNonVoid> Default for Ent<N, T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<N: Next, T: BNonVoid> Clone for Ent<N, T> {
    fn clone(&self) -> Self {
        *self
    }
}

impl<N: Next, T: BNonVoid> Copy for Ent<N, T> {}

/// Use in place of stack contents when code emitted at this point would be unreachable.
///
/// Port of `Emitter.Dead`. Note that this deliberately does *not* implement [`Next`], which is why
/// [`Emitter`] does not require `N: Next`. Java documents this interface as having no
/// implementation -- i.e., no instance of it is ever constructed -- so an uninhabited enum is the
/// faithful Rust equivalent.
pub enum Dead {}

/// The central object for emitting type-checked JVM bytecode.
///
/// Port of `ghidra.pcode.emu.jit.gen.util.Emitter<N>`. `N` encodes the contents of the operand
/// stack after all previously emitted bytecodes; see the [module docs](self).
pub struct Emitter<N> {
    /// The wrapped ASM method visitor.
    ///
    /// Port of the package-private field `mv`. Shared, because every emitter derived from this one
    /// -- by [`Clone`], by [`recast`](Self::recast), or by an op returning a new stack shape --
    /// must feed the same visitor, exactly as Java's `(Emitter) em` casts do.
    mv: Arc<Mutex<MethodVisitor>>,
    /// The root scope of local declarations.
    ///
    /// Port of the package-private field `rootScope`. `None` only for the emitter the root scope
    /// itself holds, which breaks what is a reference cycle in Java; see [`Self::new`].
    root_scope: Option<Arc<Mutex<RootScope<Bot>>>>,
    _marker: PhantomData<N>,
}

impl<N> Emitter<N> {
    /// Create a new emitter by wrapping the given method visitor.
    ///
    /// Port of the constructor `Emitter(MethodVisitor)`. As in Java, this opens the method's root
    /// scope, which places a label at the current position. Direct use is not recommended --
    /// prefer [`start`], [`start_static`], or [`start_instance`] -- but it is useful during
    /// transition from unchecked to checked bytecode generation.
    ///
    /// Java's `this.rootScope = new RootScope<>(this, 0)` makes the emitter and its root scope
    /// reference each other. Here the scope instead holds a sibling emitter over the same
    /// visitor, with no scope of its own; since everything the scope emits goes to the shared
    /// visitor, the two are indistinguishable in behavior, and the `Arc` cycle (and its leak) is
    /// avoided. The scope's stack shape is [`Bot`]: a root scope opens at method entry, where the
    /// operand stack is empty.
    pub fn new(mv: MethodVisitor) -> Self {
        let mv = Arc::new(Mutex::new(mv));
        let scope = RootScope::new(Emitter::<Bot>::detached(Arc::clone(&mv)), 0);
        Self {
            mv,
            root_scope: Some(Arc::new(Mutex::new(scope))),
            _marker: PhantomData,
        }
    }

    /// Wrap an already-shared method visitor without opening a root scope.
    fn detached(mv: Arc<Mutex<MethodVisitor>>) -> Self {
        Self { mv, root_scope: None, _marker: PhantomData }
    }

    /// Get the root scope for declaring local variables.
    ///
    /// Port of `Emitter.rootScope()`. The returned guard borrows the shared scope; hold it only
    /// for as long as the declaration takes, and do not call back into this emitter while it is
    /// held.
    ///
    /// # Panics
    ///
    /// If this is the emitter held by a root scope, which has no scope of its own. See
    /// [`Self::new`].
    pub fn root_scope(&self) -> MutexGuard<'_, RootScope<Bot>> {
        self.root_scope
            .as_ref()
            .expect("this emitter belongs to a root scope and so has none of its own")
            .lock()
            .expect("root scope lock poisoned")
    }

    /// Get the wrapped ASM method visitor.
    ///
    /// Stands in for the package-private field access `em.mv` used elsewhere in this package,
    /// e.g., by `Misc.tryCatch` and `Misc.lineNumber`.
    pub(crate) fn mv(&self) -> MutexGuard<'_, MethodVisitor> {
        self.mv.lock().expect("method visitor lock poisoned")
    }

    /// Emit `this.mv.visitLabel(label)`.
    pub fn visit_label(&mut self, label: &Label) {
        self.mv().visit_label(*label);
    }

    /// The label most recently passed to [`visit_label`](Self::visit_label), if any.
    pub fn last_visited(&self) -> Option<Label> {
        self.mv().last_visited()
    }

    /// Emit `this.mv.visitLocalVariable(name, descriptor, null, start, end, index)`.
    pub fn visit_local_variable(
        &mut self,
        name: &str,
        descriptor: &str,
        start: Label,
        end: Label,
        index: i32,
    ) {
        self.mv().visit_local_variable(name, descriptor, start, end, index);
    }

    /// The local variable declarations recorded by the wrapped visitor so far.
    ///
    /// Observable only because the visitor is a stand-in for ASM's; a real `MethodVisitor` is a
    /// write-only sink.
    pub fn local_variables(&self) -> Vec<(String, String, Label, Label, i32)> {
        self.mv().local_variables().to_vec()
    }

    /// Reinterpret this emitter's stack contents as `M`.
    ///
    /// Stands in for the unchecked `(Emitter) em` cast that every op in `Op` performs to report
    /// its effect on the stack, and that `Lbl.placeDead` performs to resurrect a [`Dead`] emitter.
    /// The wrapped visitor and root scope are shared, not copied, so the result is the same
    /// emitter in every observable respect -- just typed differently.
    pub fn recast<M>(self) -> Emitter<M> {
        Emitter { mv: self.mv, root_scope: self.root_scope, _marker: PhantomData }
    }

    /// Emit a 0-argument operator.
    ///
    /// Port of `Emitter.emit(Function)`. This can also be used to invoke generator subroutines
    /// whose only argument is the emitter.
    pub fn emit<R>(self, func: impl FnOnce(Self) -> R) -> R {
        func(self)
    }

    /// Emit a 1-argument operator.
    ///
    /// Port of `Emitter.emit(BiFunction, A1)`.
    pub fn emit1<R, A1>(self, func: impl FnOnce(Self, A1) -> R, arg1: A1) -> R {
        func(self, arg1)
    }

    /// Emit a 2-argument operator.
    ///
    /// Port of `Emitter.emit(A3Function, A1, A2)`.
    pub fn emit2<R, A1, A2>(self, func: impl FnOnce(Self, A1, A2) -> R, arg1: A1, arg2: A2) -> R {
        func(self, arg1, arg2)
    }

    /// Emit a 3-argument operator.
    ///
    /// Port of `Emitter.emit(A4Function, A1, A2, A3)`.
    pub fn emit3<R, A1, A2, A3>(
        self,
        func: impl FnOnce(Self, A1, A2, A3) -> R,
        arg1: A1,
        arg2: A2,
        arg3: A3,
    ) -> R {
        func(self, arg1, arg2, arg3)
    }

    /// Emit a 4-argument operator.
    ///
    /// Port of `Emitter.emit(A5Function, A1, A2, A3, A4)`.
    pub fn emit4<R, A1, A2, A3, A4>(
        self,
        func: impl FnOnce(Self, A1, A2, A3, A4) -> R,
        arg1: A1,
        arg2: A2,
        arg3: A3,
        arg4: A4,
    ) -> R {
        func(self, arg1, arg2, arg3, arg4)
    }

    /// Emit a 5-argument operator.
    ///
    /// Port of `Emitter.emit(A6Function, A1, A2, A3, A4, A5)`.
    #[allow(clippy::too_many_arguments)]
    pub fn emit5<R, A1, A2, A3, A4, A5>(
        self,
        func: impl FnOnce(Self, A1, A2, A3, A4, A5) -> R,
        arg1: A1,
        arg2: A2,
        arg3: A3,
        arg4: A4,
        arg5: A5,
    ) -> R {
        func(self, arg1, arg2, arg3, arg4, arg5)
    }

    /// Emit a 6-argument operator.
    ///
    /// Port of `Emitter.emit(A7Function, A1, A2, A3, A4, A5, A6)`.
    #[allow(clippy::too_many_arguments)]
    pub fn emit6<R, A1, A2, A3, A4, A5, A6>(
        self,
        func: impl FnOnce(Self, A1, A2, A3, A4, A5, A6) -> R,
        arg1: A1,
        arg2: A2,
        arg3: A3,
        arg4: A4,
        arg5: A5,
        arg6: A6,
    ) -> R {
        func(self, arg1, arg2, arg3, arg4, arg5, arg6)
    }

    /// Emit a 7-argument operator.
    ///
    /// Port of `Emitter.emit(A8Function, A1, A2, A3, A4, A5, A6, A7)`.
    #[allow(clippy::too_many_arguments)]
    pub fn emit7<R, A1, A2, A3, A4, A5, A6, A7>(
        self,
        func: impl FnOnce(Self, A1, A2, A3, A4, A5, A6, A7) -> R,
        arg1: A1,
        arg2: A2,
        arg3: A3,
        arg4: A4,
        arg5: A5,
        arg6: A6,
        arg7: A7,
    ) -> R {
        func(self, arg1, arg2, arg3, arg4, arg5, arg6, arg7)
    }
}

impl<N> Clone for Emitter<N> {
    /// Yield another handle on the same method visitor and root scope, as an unchecked cast of a
    /// Java `Emitter` reference does.
    fn clone(&self) -> Self {
        Self {
            mv: Arc::clone(&self.mv),
            root_scope: self.root_scope.clone(),
            _marker: PhantomData,
        }
    }
}

impl<N> Default for Emitter<N> {
    /// Wrap a fresh method visitor, i.e., start emitting into nothing in particular. Useful in
    /// tests; real generation should use [`start`], [`start_static`], or [`start_instance`].
    fn default() -> Self {
        Self::new(MethodVisitor::new())
    }
}

/// (Not recommended) Wrap the given method visitor with assumed stack contents.
///
/// Port of the static `Emitter.assume(MethodVisitor, N)`. [`start_static`] or [`start_instance`]
/// is recommended instead. As in Java, `assumed_stack` is only a witness for `N`; it is not
/// inspected.
pub fn assume<N: Next>(mv: MethodVisitor, _assumed_stack: N) -> Emitter<N> {
    Emitter::new(mv)
}

/// Wrap the given method visitor assuming an empty stack.
///
/// Port of the static `Emitter.start(MethodVisitor)`. [`start_static`] or [`start_instance`] is
/// recommended instead.
pub fn start(mut mv: MethodVisitor) -> Emitter<Bot> {
    mv.visit_code();
    assume(mv, BOTTOM)
}

/// Define a static method.
///
/// Port of the static `Emitter.start(ClassVisitor, int, String, MthDesc)`. `access` gets
/// `ACC_STATIC` added automatically. `MR` is the type returned by the method and `N` its parameter
/// types.
pub fn start_static<MR: BType, N: Next>(
    cv: &mut ClassVisitor,
    access: i32,
    name: &str,
    desc: &MthDesc<MR, N>,
) -> Def<MR, N> {
    let access = access | ACC_STATIC as i32;
    let mv = cv.visit_method(access, name, desc.desc());
    Def::new(start(mv), Vec::new())
}

/// Define an instance method.
///
/// Port of the static `Emitter.start(TRef, ClassVisitor, int, String, MthDesc)`. `access` gets
/// `ACC_STATIC` forcibly removed. As in Java, `owner` is only a witness for the owning type; it is
/// not inspected. Java's `OT` type parameter is dropped, since
/// [`TRef`](crate::pcode::emu::jit::gen::util::types::TRef) is not generic in this port.
pub fn start_instance<MR: BType, N: Next>(
    _owner: &TRef,
    cv: &mut ClassVisitor,
    access: i32,
    name: &str,
    desc: &MthDesc<MR, N>,
) -> ObjDef<MR, N> {
    let access = access & !(ACC_STATIC as i32);
    let mv = cv.visit_method(access, name, desc.desc());
    ObjDef::new(start(mv), Vec::new())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::pcode::emu::jit::gen::util::lbl::Lbl;
    use crate::pcode::emu::jit::gen::util::local::{self, Local};
    use crate::pcode::emu::jit::gen::util::types::{SType, TInt, T_INT, T_LONG};

    /// Java's `ACC_PUBLIC`, as passed to the `start` overloads.
    const ACC_PUBLIC: i32 = 0x0001;

    #[test]
    fn start_visits_code_then_opens_the_root_scope() {
        let em = start(MethodVisitor::new());
        // Java: start(mv) calls mv.visitCode() before constructing the emitter, ...
        assert!(em.mv().code_started());
        // ... whose constructor opens a RootScope, which places its start label immediately.
        assert!(em.last_visited().is_some());
    }

    #[test]
    fn root_scope_numbers_locals_from_zero_by_slot_count() {
        let em = start(MethodVisitor::new());
        // Java: new RootScope<>(this, 0), so a static method's first local is index 0, and a long
        // occupies two consecutive indices.
        let a = em.root_scope().decl(T_INT, "a");
        let b = em.root_scope().decl(T_LONG, "b");
        let c = em.root_scope().decl(T_INT, "c");
        assert_eq!((a.index, b.index, c.index), (0, 1, 3));
    }

    #[test]
    fn root_scope_is_shared_by_derived_emitters() {
        let em = start(MethodVisitor::new());
        let derived: Emitter<Ent<Bot, TInt>> = em.clone().recast();
        // Java's `(Emitter) em` casts yield the same object, hence the same root scope: local
        // numbering must continue rather than restart.
        let a = em.root_scope().decl(T_INT, "a");
        let b = derived.root_scope().decl(T_INT, "b");
        assert_eq!((a.index, b.index), (0, 1));
    }

    #[test]
    fn recast_preserves_the_wrapped_visitor() {
        let mut em = start(MethodVisitor::new());
        let start_lbl = Label::new();
        let end_lbl = Label::new();
        em.visit_local_variable("v", "I", start_lbl, end_lbl, 2);

        let dead: Emitter<Dead> = em.recast();
        assert_eq!(dead.local_variables().len(), 1);
        assert_eq!(dead.local_variables()[0].0, "v");
    }

    #[test]
    fn emit_chains_ops_in_the_order_written() {
        let em = start(MethodVisitor::new());
        let first = Lbl::<Bot>::create();
        let second = Lbl::<Bot>::create();

        // Java: em.emit(Lbl::place, first).emit(Lbl::place, second)
        let em = em
            .emit1(|em, l: Lbl<Bot>| l.place_at(em), first)
            .emit1(|em, l: Lbl<Bot>| l.place_at(em), second);

        assert_eq!(em.last_visited(), Some(second.label));
    }

    #[test]
    fn emit_passes_through_the_operators_result() {
        let em = start(MethodVisitor::new());
        // A generator subroutine taking only the emitter, per Java's emit(Function).
        let descriptor = em.emit(|em: Emitter<Bot>| {
            let _ = em;
            T_INT.descriptor().to_string()
        });
        assert_eq!(descriptor, "I");
    }

    #[test]
    fn emit3_forwards_all_three_arguments() {
        let em = start(MethodVisitor::new());
        let var = Local::of(T_INT, "value", 2);
        let start_lbl = Label::new();
        let end_lbl = Label::new();

        let em = em.emit3(
            |em, l: &Local<TInt>, s, e| local::decl(em, l, s, e),
            &var,
            start_lbl,
            end_lbl,
        );

        let declared = em.local_variables();
        assert_eq!(declared.len(), 1);
        assert_eq!(declared[0], ("value".to_string(), "I".to_string(), start_lbl, end_lbl, 2));
    }

    #[test]
    fn start_static_adds_the_static_flag() {
        let mut cv = ClassVisitor::new();
        let desc = MthDesc::<TInt, Bot>::new("(I)I");

        let def = start_static(&mut cv, ACC_PUBLIC, "myMethod", &desc);

        assert!(def.em.mv().code_started());
        let visited = cv.methods();
        assert_eq!(visited.len(), 1);
        assert_eq!(visited[0].access, ACC_PUBLIC | ACC_STATIC as i32);
        assert_eq!(visited[0].name, "myMethod");
        assert_eq!(visited[0].descriptor, "(I)I");
    }

    #[test]
    fn start_instance_removes_the_static_flag() {
        let mut cv = ClassVisitor::new();
        let owner = TRef::of_class("my/pkg/ImplMyIf");
        let desc = MthDesc::<TInt, Bot>::new("(ILjava/lang/String;)I");

        let _def = start_instance(
            &owner,
            &mut cv,
            ACC_PUBLIC | ACC_STATIC as i32,
            "myMethod",
            &desc,
        );

        let visited = cv.methods();
        assert_eq!(visited.len(), 1);
        assert_eq!(visited[0].access, ACC_PUBLIC);
        assert_eq!(visited[0].descriptor, "(ILjava/lang/String;)I");
    }
}
